    for (int i = 0; i < hasApple.length; i++) {
        if (hasApple[i] == true) {
            hasApple[i] = false;
        }
    }

    // Perform a binary search to find the minimum time required to collect all the apples and return to node 0
    int minTime = 0;
    int low = 0;
    int high = edges.length - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        // Check if it is possible to collect all the apples and return to node 0 in the given time
        if (check(graph, hasApple, mid)) {
            // If it is possible, update the minimum time
            minTime = mid;
            high = mid - 1;
        } else {
            // If it is not possible, update the lower bound
            low = mid + 1;
        }
    }

    // Return the minimum time
