public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    for (int i = low; i <= high; i++) {
        boolean isSteppingNumber = true;
        int previousDigit = Integer.MAX_VALUE;
        int currentNumber = i;
        while (currentNumber > 0) {
            int currentDigit = currentNumber % 10;
            if (Math.abs(previousDigit - currentDigit) > 1) {
                isSteppingNumber = false;
                break;
            }
            previousDigit = currentDigit;
            currentNumber /= 10;
        }
        if (isSteppingNumber) {
            steppingNumbers.add(i);
        }
    }
    Collections.sort(steppingNumbers);
    return steppingNumbers;
}

